changeSet.sql:
ALTER TABLE users MODIFY COLUMN created_date DATETIME(6) NOT NULL, MODIFY COLUMN last_modified_date DATETIME(6) NULL;
ALTER TABLE resource MODIFY COLUMN created_date DATETIME(6) NOT NULL, MODIFY COLUMN last_modified_date DATETIME(6) NULL;
ALTER TABLE available_slot MODIFY COLUMN start_time DATETIME(6) NOT NULL COMMENT 'Asia/Shanghai business wall-clock time', MODIFY COLUMN end_time DATETIME(6) NOT NULL COMMENT 'Asia/Shanghai business wall-clock time', MODIFY COLUMN created_date DATETIME(6) NOT NULL, MODIFY COLUMN last_modified_date DATETIME(6) NULL;
ALTER TABLE reservation MODIFY COLUMN reserved_at DATETIME(6) NOT NULL COMMENT 'UTC instant', MODIFY COLUMN cancelled_at DATETIME(6) NULL COMMENT 'UTC instant', MODIFY COLUMN completed_at DATETIME(6) NULL COMMENT 'UTC instant', MODIFY COLUMN created_date DATETIME(6) NOT NULL COMMENT 'UTC instant', MODIFY COLUMN last_modified_date DATETIME(6) NULL COMMENT 'UTC instant';
